//! 📋️ The actual private prefix owns initialized array elements until paid resident transfer.
use semio_framework_value_control_contract::{RetainedAllocationEffect,RetainedCloneStep,RetainedCloneProgress,RetirementDemand,ValueError,ValueRefusalKind,OriginalEffectReply,OriginalEffectReplyComplete,retained_clone_grant_admits};
/// 🧳️ Its private initialized count can only follow actual element publication.
/// ```compile_fail
/// let mut prefix = semio_framework_value_native_clone_engine::NativeArrayPrefix::<String, 3>::new();
/// prefix.initialized = 3;
/// ```
pub struct NativeArrayPrefix<T,const N:usize>{pub(super) slots:[std::mem::MaybeUninit<T>;N],pub(super) initialized:usize}
impl<T,const N:usize> NativeArrayPrefix<T,N>{
 pub const fn new()->Self{Self{slots:[const{std::mem::MaybeUninit::uninit()};N],initialized:0}}
 pub fn initialized(&self)->usize{self.initialized}
 pub fn is_empty(&self)->bool{self.initialized==0}
 pub fn as_slice(&self)->&[T]{unsafe{std::slice::from_raw_parts(self.slots.as_ptr().cast::<T>(),self.initialized)}}
 pub fn element_demand()->Result<RetirementDemand,ValueError>{let copy_bytes=std::mem::size_of::<T>().checked_add(std::mem::size_of::<Option<T>>()).and_then(|n|n.checked_add(std::mem::size_of::<usize>())).ok_or_else(||ValueError::invariant("native array element extent overflow"))?;Ok(RetirementDemand{copy_bytes,depth:1,..Default::default()})}
 pub fn publication_demand()->Result<RetirementDemand,ValueError>{let copy_bytes=std::mem::size_of::<[T;N]>().checked_add(std::mem::size_of::<Option<[T;N]>>()).and_then(|n|n.checked_add(std::mem::size_of::<usize>())).ok_or_else(||ValueError::invariant("native array publication extent overflow"))?;Ok(RetirementDemand{copy_bytes,depth:1,..Default::default()})}
 fn admit(effect:&mut RetainedAllocationEffect<'_>,demand:RetirementDemand)->Result<bool,ValueError>{Ok(effect.remaining_work_units()?>=1&&retained_clone_grant_admits(effect.grant(),demand))}
 fn performed(effect:&mut RetainedAllocationEffect<'_>)->Result<(),ValueError>{match effect.performed(1)?{true=>Ok(()),false=>Err(ValueError::literal(ValueRefusalKind::WorkLimit,"native prefix transfer exceeded original work"))}}
 pub fn push_from<'r>(&mut self,input:&mut Option<T>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{if self.initialized==N||input.is_none(){return Err(ValueError::invariant("native prefix requires its next original input"))}let demand=Self::element_demand()?;if !Self::admit(effect,demand)?{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}if let Err(error)=Self::performed(effect){return Ok(reply.complete(Err(error)))}self.slots[self.initialized].write(input.take().expect("native prefix input preflight"));self.initialized+=1;Ok(reply.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()}))))}
 pub fn pop_into<'r>(&mut self,output:&mut Option<T>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{if output.is_some(){return Err(ValueError::invariant("native prefix output is occupied"))}if self.initialized==0{return Ok(reply.complete(Ok(RetainedCloneStep::Complete(Default::default()))))}let demand=Self::element_demand()?;if !Self::admit(effect,demand)?{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}if let Err(error)=Self::performed(effect){return Ok(reply.complete(Err(error)))}let index=self.initialized-1;*output=Some(unsafe{self.slots[index].assume_init_read()});self.initialized=index;Ok(reply.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()}))))}
 pub fn publish_into<'r>(&mut self,output:&mut Option<[T;N]>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{if output.is_some()||self.initialized!=N{return Err(ValueError::invariant("native prefix publication requires all original elements"))}let demand=Self::publication_demand()?;if !Self::admit(effect,demand)?{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}if let Err(error)=Self::performed(effect){return Ok(reply.complete(Err(error)))}*output=Some(unsafe{std::ptr::read(self.slots.as_ptr().cast::<[T;N]>())});self.initialized=0;Ok(reply.complete(Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()}))))}
}
impl<T,const N:usize> Default for NativeArrayPrefix<T,N>{fn default()->Self{Self::new()}}
impl<T,const N:usize> Drop for NativeArrayPrefix<T,N>{fn drop(&mut self){assert!(self.is_empty()||std::thread::panicking(),"native array prefix requires original element handback")}}
